+const auditRoute = ["GET", "/audit", ({ store }) => ({ status: 200, body: [...store.data.audit].reverse() })];
+const cookPosts = new Set(["/recipes/:id/cook", "/batches/:id/waste", "/temperatures", "/stocktakes/:id/counts"]);
+
+function authenticate(headers, keys) {
+  const auth = Object.entries(headers).find(([name]) => name.toLowerCase() === "authorization")?.[1];
+  const token = typeof auth === "string" && /^Bearer +([^\s]+)$/i.exec(auth)?.[1];
+  const key = token && keys.find((entry) => entry.key === token);
+  if (!key) throw new AppError("unauthorized");
+  return key;
+}
+
+function permitted(role, method, pattern) {
+  if (role === "manager") return true;
+  if (method === "GET") return pattern !== "/audit" && (role === "cook" || role === "viewer");
+  return role === "cook" && method === "POST" && cookPosts.has(pattern);
+}
+
+const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes, auditRoute]);

